</main>
<script>
  const $=id=>document.getElementById(id); let timer=[];
  const fmt=(n,d=1)=>Number(n||0).toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d});
  $('homes').addEventListener('input',()=> $('homes-out').textContent=Number($('homes').value||0).toLocaleString()+' homes');
  $('reserve').addEventListener('input',()=> $('reserve-out').textContent=$('reserve').value+'%');
  $('apply').onclick=()=>load(false); $('drill').onclick=()=>load(true);
  function busy(on){[$('apply'),$('drill')].forEach(b=>b.disabled=on); $('drill').classList.toggle('loading',on)}
  function cards(d,stage=3){$('allocated').textContent=fmt(d.allocated_mw);$('after-failure').textContent=stage>=2?fmt(d.after_failure_mw):'—';$('redispatched').textContent=stage>=3?fmt(d.after_redispatch_mw):'—';$('card-f').classList.toggle('danger',stage===2);$('card-r').classList.toggle('active',stage>=3)}
  function workers(rows,stage){const sample=[];const step=Math.max(1,Math.floor(rows.length/60));for(let i=0;i<rows.length&&sample.length<60;i+=step)sample.push(rows[i]);$('worker-grid').innerHTML=sample.map(h=>{let s='';if(stage>=2&&h.status==='failed')s='failed';else if(stage>=3&&h.status==='boosted')s='boosted';const kw=stage>=3?h.kw_after:h.kw_before;return `<div class="worker ${s}" data-tip="#${h.id} · ${fmt(h.soc_pct,0)}% SoC · ${fmt(kw)} kW"></div>`}).join('');$('worker-note').textContent=`${sample.length} shown of ${Number(current.fleet.homes).toLocaleString()} simulated homes · hover for constraints`}
  function timeline(events,stage){$('events').innerHTML=events.map((e,i)=>`<li class="event ${i<stage?'revealed':''}"><span class="step-dot">${i+1}</span><div><b>${e.step}</b><p>${e.msg}</p></div></li>`).join('')}
  function invariants(inv){const labels={no_home_below_floor:'Dispatch respects backup floor',no_home_over_power:'No home over power limit',failed_homes_zero_output:'Offline homes at zero output'};$('invariants').innerHTML=Object.entries(inv).map(([k,v])=>`<div class="inv"><span>${labels[k]||k}</span><b class="${v?'check':'cross'}">${v?'✓ PASS':'✕ FAIL'}</b></div>`).join('')}
  let current=null;
  function render(data,drill){current=data;timer.forEach(clearTimeout);timer=[];const dec=data.decision,disp=data.dispatch,src=data.source;$('mode').className='pill '+(drill?'drill':src.mode==='LIVE'?'live':'');$('mode').innerHTML=`<i class="dot"></i>${drill?'SIMULATION · '+src.mode:src.mode}`;$('fresh').textContent='Updated '+src.last_updated.split(' ')[1]+' CT';$('action').textContent=dec.action;$('action').className='action '+dec.action.toLowerCase();$('reason').textContent=dec.reason;$('target').textContent=fmt(dec.target_mw)+' MW';$('rt').textContent=`RT $${fmt(data.now.price,2)}/MWh`;$('p25').textContent=`DAM p25 $${fmt(dec.dam_p25,2)}`;$('p75').textContent=`DAM p75 $${fmt(dec.dam_p75,2)}`;$('online').textContent=Number(data.fleet.online_after).toLocaleString()+' / '+Number(data.fleet.homes).toLocaleString();$('protected').textContent=fmt(data.fleet.reserve_mwh)+' MWh';$('value').textContent='$'+fmt(data.value.gross_usd_per_h,0)+'/h';$('shortfall').textContent=fmt(disp.shortfall_mw)+' MW';$('shortfall').style.color=disp.shortfall_mw>0.001?'var(--red)':'var(--mint)';$('source').textContent=`Official ERCOT · ${src.zone} · ${src.mode} · fleet and failures are synthetic`;invariants(data.invariants);
    if(!drill){cards(disp,3);workers(data.homes_sample,3);timeline(data.events,data.events.length);return}
    cards(disp,1);workers(data.homes_sample,1);timeline(data.events,1);
    timer.push(setTimeout(()=>{cards(disp,2);workers(data.homes_sample,2);timeline(data.events,3)},850));
    timer.push(setTimeout(()=>{cards(disp,3);workers(data.homes_sample,3);timeline(data.events,data.events.length)},1850));
  }
  async function load(drill){busy(true);try{const homes=Math.max(10,Math.min(5000,Number($('homes').value)||1000));const reserve=Number($('reserve').value)/100;const q=new URLSearchParams({zone:'lzAen',homes,reserve,drill:drill?'1':'0',fail:drill?'0.15':'0'});const res=await fetch('/api/state?'+q);const data=await res.json();if(!res.ok)throw new Error(data.error||'Request failed');render(data,drill)}catch(e){$('reason').textContent='Unable to load fleet state: '+e.message;$('action').textContent='ERROR'}finally{busy(false)}}
  load(false);
</script>
</body>
